CREATE OR REPLACE FUNCTION public.attempt_payload(p_attempt uuid, p_user uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_att public.attempts%rowtype; v_exam public.exams%rowtype; v_qs jsonb;
begin
  select * into v_att from public.attempts where id = p_attempt and user_id = p_user;
  if not found then raise exception 'attempt_not_found'; end if;
  select * into v_exam from public.exams where id = v_att.exam_id;
  if v_att.status='in_progress' and not portal_private.exam_content_ready(v_exam.question_ids,v_exam.track_id) then raise exception 'exam_content_under_review'; end if;

  select coalesce(jsonb_agg(x order by x ->> 'ord'), '[]'::jsonb) into v_qs
    from (
      select jsonb_build_object(
               'id', q.id, 'ord', lpad(ord::text, 4, '0'),
               'type', q.type, 'topic', q.topic, 'difficulty', q.difficulty,
               'stem', q.stem, 'choices', q.choices, 'assets', q.assets,
               'response', aa.response) as x
        from unnest(v_exam.question_ids) with ordinality as u(qid, ord)
        join public.questions q on q.id = u.qid
        left join public.attempt_answers aa
               on aa.attempt_id = p_attempt and aa.question_id = q.id
    ) s;

  return jsonb_build_object(
    'attempt', jsonb_build_object(
        'id', v_att.id, 'exam_id', v_att.exam_id, 'attempt_no', v_att.attempt_no,
        'status', v_att.status, 'started_at', v_att.started_at,
        'deadline_at', v_att.deadline_at, 'shuffle_seed', v_att.shuffle_seed,
        'server_now', now()),
    'exam', jsonb_build_object(
        'id', v_exam.id, 'title', v_exam.title, 'track_id', v_exam.track_id,
        'duration_seconds', v_exam.duration_seconds, 'shuffle', v_exam.shuffle),
    'questions', v_qs);
end $function$

CREATE OR REPLACE FUNCTION public.portal_start_attempt(p_exam uuid, p_user uuid, p_untimed boolean DEFAULT false)
 RETURNS attempts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_exam        public.exams%rowtype;
  v_attempt     public.attempts%rowtype;
  v_assignment  uuid;
  v_used        integer;
  v_limit       integer;
  v_grant       uuid;
  v_duration    integer;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_user::text||p_exam::text,0));
  if not exists(select 1 from profiles where id=p_user and role='student' and status='active') then raise exception 'student_account_required'; end if;
  select * into v_exam from public.exams where id = p_exam;
  if not found then
    raise exception 'exam_not_found';
  end if;
  if not v_exam.is_published then
    raise exception 'exam_not_published';
  end if;

  if p_untimed and v_exam.assessment_type <> 'lesson_exam' then
    raise exception 'untimed_lessons_only';
  end if;

  -- SAT/EST isolation. The track comes from the exam, never from the client.
  if not (public.is_enrolled(p_user, v_exam.track_id) or exists(select 1 from public.attempts a where a.user_id=p_user and a.exam_id=p_exam and a.status='in_progress' and portal_private.attempt_course_access(a.id,p_user,false))) then
    raise exception 'not_enrolled_in_track';
  end if;

  if (select status from public.profiles where id = p_user) <> 'active' then
    raise exception 'account_suspended';
  end if;

  -- Finalise this student's own stale attempt on this exam before anything
  -- else, so an abandoned session never blocks the partial unique index.
  perform public.finalize_expired_for(p_user, p_exam);

  if not portal_private.exam_content_ready(v_exam.question_ids,v_exam.track_id) then raise exception 'exam_content_under_review'; end if;

  -- Resume a live attempt rather than creating a second one.
  select * into v_attempt from public.attempts
   where user_id = p_user and exam_id = p_exam and status = 'in_progress';
  if found then
    return v_attempt;
  end if;

  v_assignment := public.student_assignment_for(p_exam, p_user);
  if v_assignment is null then
    raise exception 'not_assigned_or_window_closed';
  end if;

  select count(*) into v_used from public.attempts
   where user_id = p_user and exam_id = p_exam;
  v_limit := 1;

  if v_used >= v_limit and v_exam.assessment_type <> 'lesson_exam' then
    select id into v_grant from public.retake_grants
     where user_id = p_user and exam_id = p_exam
       and consumed_at is null
       and (expires_at is null or expires_at > now())
     order by granted_at limit 1 for update;
    if v_grant is null then
      raise exception 'attempt_limit_reached';
    end if;
    update public.retake_grants set consumed_at = now() where id = v_grant;
    insert into public.audit_log(actor_id, action, target_type, target_id, meta)
    values (p_user, 'retake.consumed', 'exam', p_exam::text,
            jsonb_build_object('grant_id', v_grant));
  end if;

  v_duration := coalesce(nullif(v_exam.duration_seconds, 0),
                         (select default_duration_seconds from public.tracks where id = v_exam.track_id));

  insert into public.attempts(user_id, exam_id, assignment_id, attempt_no,
                              shuffle_seed, deadline_at, total)
  values (p_user, p_exam, v_assignment, v_used + 1,
          (floor(random() * 2147483646) + 1)::bigint,
          case when p_untimed then 'infinity'::timestamptz else now() + make_interval(secs => v_duration) end,
          coalesce(array_length(v_exam.question_ids, 1), 0))
  returning * into v_attempt;

  insert into public.audit_log(actor_id, action, target_type, target_id, meta)
  values (p_user, 'attempt.started', 'attempt', v_attempt.id::text,
          jsonb_build_object('exam_id', p_exam, 'attempt_no', v_attempt.attempt_no));

  return v_attempt;

exception when unique_violation then
  -- Two starts raced. The index kept one; return the survivor.
  select * into v_attempt from public.attempts
   where user_id = p_user and exam_id = p_exam and status = 'in_progress';
  if found then return v_attempt; end if;
  raise;
end $function$

CREATE OR REPLACE FUNCTION public.portal_admin(p_actor uuid, p_action text, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare role_ text; track_ text; id_ uuid; q jsonb; ids uuid[]; result_ jsonb; old_ jsonb; student_ uuid; group_ uuid; exam_ uuid; n int;
begin
 select role into role_ from profiles where id=p_actor and status='active';
 if role_ is null or role_ not in ('admin','instructor') then raise exception 'forbidden'; end if;
 if p_action in ('user.update','enrollment.save','device.revoke','instructor.tracks') and role_<>'admin' then raise exception 'admin_required'; end if;
 track_=p_data->>'track_id'; id_=nullif(p_data->>'id','')::uuid;
 if p_action like 'question.%' and id_ is not null then select track_id into track_ from questions where id=id_ for update; end if;
 if p_action in ('exam.save','exam.classify') and id_ is not null then select track_id into track_ from exams where id=id_ for update; end if;
 if p_action in ('assignment.save','review.release') then select track_id into track_ from exams where id=(p_data->>'exam_id')::uuid; end if;
 if p_action='group.save' and id_ is not null then select track_id into track_ from groups where id=id_; end if;
 if p_action in ('question.save','question.import','exam.save','exam.classify','assignment.save','group.save','review.release') then
  if track_ is null or not exists(select 1 from tracks where id=track_ and is_active) then raise exception 'invalid_track'; end if;
  if role_='instructor' and not exists(select 1 from instructor_tracks where user_id=p_actor and track_id=track_) then raise exception 'forbidden_track'; end if;
 end if;
 if p_action in ('question.save','question.import') then
  if p_action='question.import' and (jsonb_typeof(p_data->'questions')<>'array' or jsonb_array_length(p_data->'questions') not between 1 and 500) then raise exception 'provide_1_to_500_questions'; end if;
  result_='[]'::jsonb;
  for q in select value from jsonb_array_elements(case when p_action='question.import' then p_data->'questions' else jsonb_build_array(p_data) end) loop
   if p_action='question.import' then id_=null; end if;
   if length(trim(coalesce(q->>'stem','')))=0 or q->>'type' not in ('mcq','grid_in') or q->>'type' is null then raise exception 'invalid_question'; end if;
   if not(q ? 'correct') or q->'correct'='null'::jsonb then raise exception 'answer_key_required'; end if;
   if coalesce(q->>'difficulty','medium') not in ('easy','medium','hard') then raise exception 'invalid_difficulty'; end if;
   if q->>'type'='mcq' then
    if jsonb_typeof(q->'choices') is distinct from 'array' or jsonb_array_length(q->'choices') not between 2 and 8 then raise exception 'invalid_choices'; end if;
    if exists(select 1 from jsonb_array_elements(q->'choices') c where coalesce(c->>'key','')='' or coalesce(c->>'text','')='') or (select count(distinct c->>'key') from jsonb_array_elements(q->'choices') c)<>jsonb_array_length(q->'choices') then raise exception 'invalid_choice_keys'; end if;
    if jsonb_typeof(q->'correct')<>'string' or not exists(select 1 from jsonb_array_elements(q->'choices') c where c->>'key'=q->>'correct') then raise exception 'correct_choice_missing'; end if;
   else
    if jsonb_typeof(q->'correct') not in ('string','array') then raise exception 'invalid_grid_in_key'; end if;
    if jsonb_typeof(q->'correct')='array' and (jsonb_array_length(q->'correct')=0 or exists(select 1 from jsonb_array_elements(q->'correct') c where jsonb_typeof(c)<>'string')) then raise exception 'invalid_grid_in_key'; end if;
   end if;
   if id_ is not null and exists(select 1 from exams e where id_=any(e.question_ids) and (e.is_published or exists(select 1 from attempts a where a.exam_id=e.id))) then raise exception 'question_in_use_create_new_version'; end if;
   id_=coalesce(id_,gen_random_uuid());
   insert into questions(id,track_id,topic,difficulty,type,stem,choices,assets) values(id_,track_,coalesce(q->>'topic',''),coalesce(q->>'difficulty','medium'),q->>'type',q->>'stem',coalesce(q->'choices','[]'),coalesce(q->'assets','{}'))
   on conflict(id) do update set topic=excluded.topic,difficulty=excluded.difficulty,type=excluded.type,stem=excluded.stem,choices=excluded.choices,assets=excluded.assets;
   insert into question_keys values(id_,q->'correct',coalesce(q->>'explanation','')) on conflict(question_id) do update set correct=excluded.correct,explanation=excluded.explanation;
   result_=result_||jsonb_build_array(id_);
  end loop;
  result_=jsonb_build_object('question_ids',result_);
 elsif p_action='exam.classify' then
  update exams set assessment_type=p_data->>'assessment_type' where id=id_;
  if not found then raise exception 'exam_not_found'; end if;
  result_=jsonb_build_object('id',id_);
 elsif p_action='exam.save' then
  if id_ is not null and (p_data-'id'-'is_published')='{}'::jsonb then
   update exams set is_published=(p_data->>'is_published')::boolean where id=id_; result_=jsonb_build_object('id',id_);
  else
   if id_ is not null and exists(select 1 from attempts where exam_id=id_) then raise exception 'exam_has_attempts_create_new_version'; end if;
   select array_agg(value::uuid) into ids from jsonb_array_elements_text(p_data->'question_ids');
   if ids is null or cardinality(ids)>200 or (select count(distinct x) from unnest(ids) x)<>cardinality(ids) then raise exception 'select_1_to_200_unique_questions'; end if;
   if (select count(*) from questions q join question_keys k on k.question_id=q.id where q.id=any(ids) and q.track_id=track_)<>cardinality(ids) then raise exception 'question_track_or_key_mismatch'; end if;
   if length(trim(coalesce(p_data->>'title','')))=0 or (p_data->>'duration_seconds')::int not between 60 and 14400 then raise exception 'invalid_title_or_duration'; end if;
   if p_data->'scoring_map' is not null and p_data->'scoring_map'<>'null'::jsonb then
    if jsonb_typeof(p_data->'scoring_map')<>'object' or exists(select 1 from generate_series(0,cardinality(ids)) x where not(p_data->'scoring_map' ? x::text) or (p_data->'scoring_map'->>x::text)!~'^\d+$') then raise exception 'scoring_map_must_cover_every_raw_score'; end if;
   end if;
   id_=coalesce(id_,gen_random_uuid());
   insert into exams(id,track_id,title,duration_seconds,question_ids,shuffle,max_attempts,is_published,is_full_length,scoring_map,review_policy,assessment_type)
   values(id_,track_,p_data->>'title',(p_data->>'duration_seconds')::int,ids,true,1,coalesce((p_data->>'is_published')::boolean,false),coalesce((p_data->>'is_full_length')::boolean,false),nullif(p_data->'scoring_map','null'),coalesce(p_data->>'review_policy','full_review'),coalesce(p_data->>'assessment_type',case when (p_data->>'is_full_length')::boolean then 'full_exam' else 'lesson_exam' end))
   on conflict(id) do update set title=excluded.title,duration_seconds=excluded.duration_seconds,question_ids=excluded.question_ids,is_published=excluded.is_published,is_full_length=excluded.is_full_length,scoring_map=excluded.scoring_map,review_policy=excluded.review_policy,assessment_type=excluded.assessment_type;
   result_=jsonb_build_object('id',id_);
  end if;
 elsif p_action='assignment.save' then
  exam_=(p_data->>'exam_id')::uuid; student_=nullif(p_data->>'user_id','')::uuid; group_=nullif(p_data->>'group_id','')::uuid;
  if (student_ is null)=(group_ is null) then raise exception 'one_assignment_target_required'; end if;
  if student_ is not null and not is_enrolled(student_,track_) then raise exception 'student_not_enrolled'; end if;
  if group_ is not null and not exists(select 1 from groups where id=group_ and track_id=track_ and (role_='admin' or instructor_id=p_actor)) then raise exception 'forbidden_group'; end if;
  if role_='instructor' and student_ is not null and not exists(select 1 from group_members gm join groups g on g.id=gm.group_id where gm.user_id=student_ and g.track_id=track_ and g.instructor_id=p_actor) then raise exception 'student_outside_your_groups'; end if;
  if (p_data->>'close_at')::timestamptz <= (p_data->>'open_at')::timestamptz then raise exception 'close_must_follow_open'; end if;
  if id_ is not null and exists(select 1 from attempts where assignment_id=id_) then raise exception 'assignment_has_attempts'; end if;
  if id_ is not null and not exists(select 1 from assignments where id=id_ and exam_id=exam_) then raise exception 'assignment_exam_mismatch'; end if;
  id_=coalesce(id_,gen_random_uuid());
  insert into assignments(id,exam_id,user_id,group_id,open_at,close_at) values(id_,exam_,student_,group_,(p_data->>'open_at')::timestamptz,(p_data->>'close_at')::timestamptz)
  on conflict(id) do update set user_id=excluded.user_id,group_id=excluded.group_id,open_at=excluded.open_at,close_at=excluded.close_at;
  result_=jsonb_build_object('id',id_);
 elsif p_action='group.save' then
  if length(trim(coalesce(p_data->>'name','')))=0 then raise exception 'group_name_required'; end if;
  if id_ is not null and role_='instructor' and not exists(select 1 from groups where id=id_ and instructor_id=p_actor) then raise exception 'forbidden_group'; end if;
  id_=coalesce(id_,gen_random_uuid());
  insert into groups(id,track_id,name,instructor_id) values(id_,track_,p_data->>'name',case when role_='instructor' then p_actor else nullif(p_data->>'instructor_id','')::uuid end)
  on conflict(id) do update set name=excluded.name,instructor_id=excluded.instructor_id;
  if p_data ? 'user_ids' then
   select coalesce(array_agg(value::uuid),'{}') into ids from jsonb_array_elements_text(p_data->'user_ids');
   if exists(select 1 from unnest(ids) u where not is_enrolled(u,track_)) then raise exception 'group_member_not_enrolled'; end if;
   delete from group_members where group_id=id_;
   insert into group_members select id_,u from unnest(ids) u on conflict do nothing;
  end if;
  result_=jsonb_build_object('id',id_);
 elsif p_action='user.update' then
  if id_=p_actor and (p_data->>'role'<>'admin' or p_data->>'status'='suspended') then raise exception 'cannot_remove_own_admin_access'; end if;
  update profiles set full_name=coalesce(p_data->>'full_name',full_name),role=coalesce(p_data->>'role',role),status=coalesce(p_data->>'status',status) where id=id_;
  if not found then raise exception 'user_not_found'; end if;
  result_=jsonb_build_object('id',id_);
 elsif p_action='instructor.tracks' then
  if not exists(select 1 from profiles where id=id_ and role='instructor') then raise exception 'instructor_required'; end if;
  delete from instructor_tracks where user_id=id_;
  insert into instructor_tracks select id_,value from jsonb_array_elements_text(p_data->'tracks');
  result_=jsonb_build_object('id',id_);
 elsif p_action='enrollment.save' then
  student_=(p_data->>'user_id')::uuid;
  if p_data->>'status'='active' then perform enrol_student(student_,track_,p_actor);
  elsif p_data->>'status'='paused' then update enrollments set status='paused' where user_id=student_ and track_id=track_;
  else raise exception 'invalid_status'; end if;
  result_=jsonb_build_object('user_id',student_);
 elsif p_action='device.revoke' then
  update device_sessions set revoked_at=now() where id=id_ returning user_id into student_;
  if not found then raise exception 'device_not_found'; end if;
  result_=jsonb_build_object('id',id_);
 elsif p_action='review.release' then
  exam_=(p_data->>'exam_id')::uuid;
  if exists(select 1 from assignments where exam_id=exam_ and close_at>now()) then raise exception 'assignment_window_still_open'; end if;
  update exams set review_policy='full_review' where id=exam_;
  update attempts set review_unlocks_at=now() where exam_id=exam_ and status in ('graded','expired');
  result_=jsonb_build_object('exam_id',exam_);
 else raise exception 'unknown_action';
 end if;
 insert into audit_log(actor_id,action,target_type,target_id,meta) values(p_actor,p_action,split_part(p_action,'.',1),id_::text,jsonb_build_object('track_id',track_,'result',result_));
 return result_;
end $function$

CREATE OR REPLACE FUNCTION public.portal_manage(p_actor uuid, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare group_ uuid; scope_ uuid; groups_ jsonb; role_ text; track_ text:=p_data->>'track'; id_ uuid; ids_ uuid[]; c public.portal_track_controls%rowtype; data_ jsonb; n int; student_ uuid; mode_ text; day_ date; before_ jsonb; report_ public.portal_reports%rowtype;
begin
 select role into role_ from public.profiles where id=p_actor and status='active';
 if role_ is null or role_ not in ('admin','instructor') then raise exception 'staff_required';end if;
 if track_ is null or not exists(select 1 from public.tracks where id=track_ and is_active) then raise exception 'choose_track';end if;
 if role_='instructor' and not exists(select 1 from public.instructor_tracks where user_id=p_actor and track_id=track_) then raise exception 'forbidden_track';end if;
 select * into c from public.portal_track_controls where track_id=track_;
 if p_action in ('quiz.list','quiz.reset') then
  select coalesce(jsonb_agg(jsonb_build_object('id',g.id,'name',g.name) order by lower(g.name),g.id),'[]'::jsonb) into groups_
   from public.groups g where g.track_id=track_ and (role_='admin' or g.instructor_id=p_actor);
  if p_action='quiz.reset' and not p_data ? 'group_id' then raise exception 'quiz_group_required'; end if;
  if p_data ? 'group_id' then scope_:=(p_data->>'group_id')::uuid;
  else scope_:=coalesce((groups_->0->>'id')::uuid,'00000000-0000-0000-0000-000000000000'::uuid); end if;
  if scope_ is null then raise exception 'quiz_group_required'; end if;
  group_:=nullif(scope_,'00000000-0000-0000-0000-000000000000'::uuid);
  if group_ is not null and not exists(select 1 from public.groups g where g.id=group_ and g.track_id=track_ and (role_='admin' or g.instructor_id=p_actor)) then raise exception 'group_scope_denied'; end if;
 end if;
 if p_action='revision.list' then
  select coalesce(jsonb_agg(jsonb_build_object('id',r.question_id,'lesson',r.lesson,'idea',r.idea,'difficulty',r.difficulty,'active',r.active,'source',coalesce(q.assets->>'source_code',q.assets->>'code',''),'stem',q.stem,'ready',r.fingerprint=public.revision_question_fingerprint(q.stem,q.choices,q.assets,k.correct,k.explanation) and nullif(q.assets->>'release_hold_reason','') is null) order by r.lesson,r.idea,r.question_id),'[]') into data_
  from public.revision_items r join public.questions q on q.id=r.question_id join public.question_keys k on k.question_id=q.id where q.track_id=track_;
  return jsonb_build_object('visible',c.revision_visible,'items',data_);
 elsif p_action='quiz.list' then
  return jsonb_build_object('group_id',scope_,'groups',groups_,'group_name',coalesce((select name from public.groups where id=group_),'Earlier course quiz'),'settings',to_jsonb(c),'today_frozen',exists(select 1 from public.daily_progress where track_id=track_ and day=(now() at time zone 'Africa/Cairo')::date),
   'today',(select jsonb_build_object('day',day,'question_ids',question_ids) from public.daily_quizzes where track_id=track_ and day=(now() at time zone 'Africa/Cairo')::date),
   'questions',(select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'lesson',q.topic,'stem',q.stem,'source',coalesce(q.assets->>'source_code',q.assets->>'code','')) order by q.topic,q.id),'[]') from public.questions q join public.question_keys k on k.question_id=q.id where q.track_id=track_ and q.type='mcq' and nullif(q.assets->>'verified_release','') is not null and nullif(q.assets->>'release_hold_reason','') is null and length(btrim(k.explanation))>0 and jsonb_array_length(q.choices)>=4 and jsonb_typeof(k.correct)='string' and exists(select 1 from jsonb_array_elements(q.choices) ch where ch->>'key'=k.correct#>>'{}')),
   'students',(select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'name',p.full_name,'completed',coalesce(d.completed,0),'points',coalesce(d.points,0),'score_today',d.score_today,'average_score',d.average_score) order by p.full_name),'[]') from public.profiles p join public.enrollments e on e.user_id=p.id and e.track_id=track_ left join lateral(select count(quiz_completed_at) completed,sum(points) points,max(quiz_score) filter(where day=(now() at time zone 'Africa/Cairo')::date) score_today,round(avg(quiz_score),2) average_score from public.daily_progress dp where dp.user_id=p.id and dp.track_id=track_ and dp.quiz_group_id is not distinct from group_) d on true where p.role='student' and not p.is_test and (group_ is null or exists(select 1 from public.group_members gm where gm.group_id=group_ and gm.user_id=p.id) or exists(select 1 from public.daily_progress dp where dp.user_id=p.id and dp.track_id=track_ and dp.quiz_group_id=group_)) and (role_='admin' or exists(select 1 from public.groups g join public.group_members gm on gm.group_id=g.id where gm.user_id=p.id and g.instructor_id=p_actor and g.track_id=track_))));
 elsif p_action='reports.list' then
  select coalesce(jsonb_agg(x order by x->>'created_at' desc),'[]') into data_ from (
   select to_jsonb(r)||jsonb_build_object('student',p.full_name,'question_stem',q.stem,'source',q.assets->>'source_code') x from public.portal_reports r join public.profiles p on p.id=r.user_id left join public.questions q on q.id=r.question_id
   where r.track_id=track_ and (role_='admin' or r.user_id=p_actor or exists(select 1 from public.groups g join public.group_members gm on gm.group_id=g.id where gm.user_id=r.user_id and g.instructor_id=p_actor and g.track_id=track_)) and (coalesce(p_data->>'status','all')='all' or r.status=p_data->>'status') order by r.created_at desc limit 200) z;
  return jsonb_build_object('items',data_,'open_count',(select count(*) from public.portal_reports r where r.track_id=track_ and (role_='admin' or r.user_id=p_actor or exists(select 1 from public.groups g join public.group_members gm on gm.group_id=g.id where gm.user_id=r.user_id and g.instructor_id=p_actor and g.track_id=track_)) and r.status in ('open','in_review')));
 elsif p_action='revision.visibility' then
  if jsonb_typeof(p_data->'visible') is distinct from 'boolean' then raise exception 'invalid_visibility';end if;
  update public.portal_track_controls set revision_visible=(p_data->>'visible')::boolean,updated_at=now() where track_id=track_;
  data_:=jsonb_build_object('visible',(p_data->>'visible')::boolean);
 elsif p_action='revision.release' then
  if jsonb_typeof(p_data->'active') is distinct from 'boolean' then raise exception 'invalid_release';end if;
  select array_agg(x::uuid) into ids_ from jsonb_array_elements_text(p_data->'ids') x;
  if coalesce(cardinality(ids_),0) not between 1 and 1000 or (select count(distinct x) from unnest(ids_) x)<>cardinality(ids_) then raise exception 'select_questions';end if;
  if (select count(*) from public.revision_items r join public.questions q on q.id=r.question_id where r.question_id=any(ids_) and q.track_id=track_)<>cardinality(ids_) then raise exception 'question_track_mismatch';end if;
  if (p_data->>'active')::boolean and exists(select 1 from public.revision_items r join public.questions q on q.id=r.question_id join public.question_keys k on k.question_id=q.id where r.question_id=any(ids_) and (r.fingerprint<>public.revision_question_fingerprint(q.stem,q.choices,q.assets,k.correct,k.explanation) or nullif(q.assets->>'release_hold_reason','') is not null)) then raise exception 'questions_need_review';end if;
  update public.revision_items set active=(p_data->>'active')::boolean where question_id=any(ids_);
  data_:=jsonb_build_object('count',cardinality(ids_),'active',(p_data->>'active')::boolean);
 elsif p_action='quiz.save' then
  mode_:=p_data->>'mode';if mode_ is null or mode_ not in ('random','lessons','selected') then raise exception 'invalid_quiz_mode';end if;
  select coalesce(array_agg(x::uuid),'{}') into ids_ from jsonb_array_elements_text(coalesce(p_data->'ids','[]')) x;
  if cardinality(ids_)>1000 or (select count(distinct x) from unnest(ids_) x)<>cardinality(ids_) then raise exception 'invalid_question_selection';end if;
  if mode_='selected' and cardinality(ids_)<5 then raise exception 'select_at_least_five_questions';end if;
  select count(*) into n from public.questions q join public.question_keys k on k.question_id=q.id where q.track_id=track_ and q.type='mcq' and nullif(q.assets->>'verified_release','') is not null and nullif(q.assets->>'release_hold_reason','') is null and length(btrim(k.explanation))>0 and jsonb_array_length(q.choices)>=4 and jsonb_typeof(k.correct)='string' and exists(select 1 from jsonb_array_elements(q.choices) ch where ch->>'key'=k.correct#>>'{}') and (mode_='random' or (mode_='selected' and q.id=any(ids_)) or (mode_='lessons' and coalesce(p_data->'lessons','[]') ? q.topic));
  if n<5 then raise exception 'quiz_pool_needs_five_valid_questions';end if;
  if mode_='selected' and n<>cardinality(ids_) then raise exception 'selected_question_unavailable';end if;
  -- Same lock as daily_state: selecting today's questions cannot race an edit.
  perform pg_advisory_xact_lock(hashtextextended('daily:'||track_||':'||(now() at time zone 'Africa/Cairo')::date::text,0));
  update public.portal_track_controls set daily_mode=mode_,daily_question_ids=case when mode_='selected' then ids_ else '{}'::uuid[] end,daily_lessons=case when mode_='lessons' then array(select jsonb_array_elements_text(p_data->'lessons')) else '{}'::text[] end,updated_at=now() where track_id=track_;
  if not exists(select 1 from public.daily_progress where track_id=track_ and day=(now() at time zone 'Africa/Cairo')::date) then delete from public.daily_quizzes where track_id=track_ and day=(now() at time zone 'Africa/Cairo')::date;end if;
  data_:=jsonb_build_object('mode',mode_,'eligible',n,'today_frozen',exists(select 1 from public.daily_progress where track_id=track_ and day=(now() at time zone 'Africa/Cairo')::date));
 elsif p_action='quiz.reset' then
  if role_<>'admin' then raise exception 'admin_required';end if;
  if p_data->>'confirm' is distinct from 'RESET' then raise exception 'reset_confirmation_required';end if;
  student_:=(p_data->>'user_id')::uuid; mode_:=p_data->>'mode';day_:=nullif(p_data->>'day','')::date;
  if mode_ is null or mode_ not in ('quiz','all') then raise exception 'invalid_reset_mode';end if;
  if not exists(select 1 from public.enrollments e join public.profiles p on p.id=e.user_id where e.user_id=student_ and e.track_id=track_ and p.role='student') then raise exception 'student_not_enrolled';end if;
  if day_ is null and p_data->>'range' is distinct from 'all' then raise exception 'reset_date_required';end if;
  perform pg_advisory_xact_lock(hashtextextended('daily:'||coalesce(group_::text,track_)||':'||(now() at time zone 'Africa/Cairo')::date::text,0));
  perform 1 from public.daily_progress where user_id=student_ and track_id=track_ and quiz_group_id is not distinct from group_ and (day_ is null or day=day_) for update;
  select coalesce(jsonb_agg(to_jsonb(dp)),'[]') into before_ from public.daily_progress dp where user_id=student_ and track_id=track_ and quiz_group_id is not distinct from group_ and (day_ is null or day=day_);
  insert into public.daily_reset_archive(actor_id,user_id,track_id,reset_mode,previous_progress) values(p_actor,student_,track_,mode_,before_) returning id into id_;
  if mode_='all' then delete from public.daily_progress where user_id=student_ and track_id=track_ and quiz_group_id is not distinct from group_ and (day_ is null or day=day_);
  else update public.daily_progress set quiz_completed_at=null,quiz_score=null,answers='{}',points=0,bonus_awarded=false where user_id=student_ and track_id=track_ and quiz_group_id is not distinct from group_ and (day_ is null or day=day_);end if;
  get diagnostics n=row_count;
  data_:=jsonb_build_object('count',n,'archive_id',id_);
 elsif p_action='reports.update' then
  id_:=(p_data->>'id')::uuid;
  if p_data->>'status' is null or p_data->>'status' not in ('open','in_review','resolved','dismissed') or length(coalesce(p_data->>'note',''))>2000 then raise exception 'invalid_report_status';end if;
  update public.portal_reports r set status=p_data->>'status',staff_note=coalesce(p_data->>'note',''),updated_at=now() where r.id=id_ and r.track_id=track_ and (role_='admin' or r.user_id=p_actor or exists(select 1 from public.groups g join public.group_members gm on gm.group_id=g.id where gm.user_id=r.user_id and g.instructor_id=p_actor and g.track_id=track_));
  if not found then raise exception 'report_not_found';end if;
  data_:=jsonb_build_object('id',id_,'status',p_data->>'status');
 else raise exception 'invalid_action';end if;
 insert into public.audit_log(actor_id,action,target_type,target_id,meta) values(p_actor,p_action,split_part(p_action,'.',1),coalesce(id_::text,track_),jsonb_build_object('track',track_,'result',data_));
 return data_;
end $function$

CREATE OR REPLACE FUNCTION public.portal_session(p_user uuid, p_session uuid, p_agent text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d public.device_sessions;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
 if not exists(select 1 from auth.sessions where id=p_session and user_id=p_user) then raise exception 'invalid_session'; end if;
 select * into d from device_sessions where session_id=p_session;
 if found then
  if d.revoked_at is not null then raise exception 'device_revoked'; end if;
  update device_sessions set last_seen=now() where id=d.id; return;
 end if;
 if (select count(*) from device_sessions ds join auth.sessions s on s.id=ds.session_id where ds.user_id=p_user and ds.revoked_at is null and ds.last_seen>now()-interval '30 days')>=3 then raise exception 'device_limit_reached'; end if;
 insert into device_sessions(user_id,device_hash,session_id,user_agent) values(p_user,p_session::text,p_session,left(p_agent,500));
 insert into audit_log(actor_id,action,target_type,target_id) values(p_user,'device.registered','session',p_session::text);
end $function$

CREATE OR REPLACE FUNCTION public.portal_student_controls(p_user uuid, p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare track_ text:=p_data->>'track'; role_ text; id_ uuid; request_ uuid; qid uuid;
begin
 select role into role_ from public.profiles where id=p_user and status='active';
 if role_ is null or not exists(select 1 from public.tracks where id=track_ and (is_active or (p_action='settings' and public.course_history_access(p_user,track_)))) then raise exception 'forbidden';end if;
 if role_='student' and not (public.is_enrolled(p_user,track_) or (p_action='settings' and public.course_history_access(p_user,track_))) then raise exception 'not_enrolled_in_track';end if;
 if role_='instructor' and not exists(select 1 from public.instructor_tracks where user_id=p_user and track_id=track_) then raise exception 'forbidden_track';end if;
 if p_action='settings' then
  return jsonb_build_object('track',track_,'revision_visible',track_ in ('sat','est','est2') and coalesce((select revision_visible from public.portal_track_controls where track_id=track_),false));
 end if;
 if p_action<>'report' then raise exception 'invalid_action';end if;
 request_:=(p_data->>'request_id')::uuid;
 if request_ is null then raise exception 'request_id_required';end if;
 select id into id_ from public.portal_reports where user_id=p_user and request_id=request_;
 if id_ is not null then return jsonb_build_object('id',id_,'status','received');end if;
 if p_data->>'kind' not in ('question','functionality') or p_data->>'kind' is null or length(btrim(coalesce(p_data->>'message',''))) not between 10 and 3000 then raise exception 'describe_report_10_to_3000_characters';end if;
 qid:=nullif(p_data->>'question_id','')::uuid;
 if (p_data->>'kind'='question')<>(qid is not null) then raise exception 'question_required';end if;
 if qid is not null and not exists(select 1 from public.questions q where q.id=qid and (q.track_id=track_ or (track_='sat' and exists(select 1 from public.revision_items r where r.question_id=q.id and r.programmes @> array[track_])))) then raise exception 'question_track_mismatch';end if;
 perform pg_advisory_xact_lock(hashtextextended('report:'||p_user::text,0));
 select id into id_ from public.portal_reports where user_id=p_user and request_id=request_;
 if id_ is not null then return jsonb_build_object('id',id_,'status','received');end if;
 if (select count(*) from public.portal_reports where user_id=p_user and created_at>now()-interval '1 hour')>=10 then raise exception 'report_limit_try_later';end if;
 insert into public.portal_reports(user_id,track_id,request_id,kind,question_id,screen,message)
 values(p_user,track_,request_,p_data->>'kind',qid,left(coalesce(p_data->>'screen',''),100),btrim(p_data->>'message'))
 on conflict(user_id,request_id) do update set request_id=excluded.request_id returning id into id_;
 return jsonb_build_object('id',id_,'status','received');
end $function$

CREATE OR REPLACE FUNCTION public.portal_submit(p_attempt uuid, p_user uuid, p_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare cached portal_private.submissions; payload jsonb;
begin
 perform 1 from attempts a join exams e on e.id=a.exam_id where a.id=p_attempt and a.user_id=p_user and (course_history_access(p_user,e.track_id) and (a.status<>'in_progress' or portal_private.attempt_course_access(a.id,p_user,true))) for update of a;
 if not found then raise exception 'attempt_not_found'; end if;
 select * into cached from portal_private.submissions where attempt_id=p_attempt and user_id=p_user;
 if p_key is not null and cached.idempotency_key=p_key then return jsonb_build_object('status',200,'body',cached.response); end if;
 if (select status from attempts where id=p_attempt)<>'in_progress' then
  return jsonb_build_object('status',409,'body',jsonb_build_object('error','already_submitted','result',attempt_review(p_attempt,p_user)));
 end if;
 perform submit_attempt(p_attempt,p_user);
 payload=attempt_review(p_attempt,p_user);
 if p_key is not null then
  if length(p_key)>128 then raise exception 'invalid_idempotency_key'; end if;
  insert into portal_private.submissions values(p_attempt,p_user,p_key,payload);
 end if;
 return jsonb_build_object('status',200,'body',payload);
end $function$

CREATE OR REPLACE FUNCTION public.submit_attempt(p_attempt uuid, p_user uuid)
 RETURNS attempts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_att public.attempts%rowtype;
begin
  update public.attempts
     set status = 'submitted', submitted_at = least(clock_timestamp(),deadline_at)
   where id = p_attempt and user_id = p_user and status = 'in_progress'
  returning * into v_att;

  if not found then
    select * into v_att from public.attempts where id = p_attempt and user_id = p_user;
    if not found then
      raise exception 'attempt_not_found';
    end if;
    raise exception 'already_submitted';
  end if;

  insert into public.audit_log(actor_id, action, target_type, target_id, meta)
  values (p_user, 'attempt.submitted', 'attempt', p_attempt::text,
          jsonb_build_object('exam_id', v_att.exam_id));

  perform public.grade_attempt(p_attempt);
  if clock_timestamp() >= v_att.deadline_at then update attempts set status='expired' where id=p_attempt; end if;
  select * into v_att from attempts where id=p_attempt;
  return v_att;
end $function$

